[asy]
unitsize(3 cm);

pair A, O, T;

real func (real x) {
  return ((x - 1)*(x - 2));
}

A = (1.5,-0.4);
O = (0,0);
T = intersectionpoint(Circle(A,abs(A - (1,0))),arc(A/2,abs(A)/2,0,90));

